	private static void refineMappedPhysicalJoinCost(PackedCostContext context, PackedCostEstimate output) {
		if (!"independent-hash".equals(output.plannedStringMetric("optimizer.physicalJoinImplementation"))
				|| !finiteNonNegative(output.outputRows())
				|| !finiteNonNegative(context.leftInputRows())
				|| !finiteNonNegative(context.rightInputRows())) {
			return;
		}
		double executionPartitions = finiteNonNegative(output.invocations()) && output.invocations() > 0.0d
				? output.invocations()
				: 1.0d;
		LmdbHashJoinCosting.CandidateEstimate candidates = LmdbHashJoinCosting.estimateCandidates(
				context.leftInputRows(), context.rightInputRows(), executionPartitions, output.outputRows(),
				context.hashLookupMaskId(), context.hashCompatibilityMaskId(), null, null);
		boolean requireRightBuild = "right".equals(
				output.plannedStringMetric("optimizer.hashJoinRequiredBuildSide"));
		LmdbHashJoinCosting.Orientation orientation = requireRightBuild
				? LmdbHashJoinCosting.rightBuildOrientation(
						context.leftInputRows(), context.rightInputRows(), executionPartitions,
						candidates.candidateRows(), output.outputRows())
				: LmdbHashJoinCosting.chooseOrientation(
						context.leftInputRows(), context.rightInputRows(), executionPartitions,
						candidates.candidateRows(), output.outputRows(),
						MinusQueryEvaluationStep.maxMaterializedRightRows());
		double probeRows = saturatedAdd(orientation.probeInputRows(), candidates.candidateRows());
		output.setLocalPhysicalCost(
				0.0d, 0.0d, 0.0d, 0.0d, orientation.buildRows(), probeRows, 0.0d, output.outputRows(), 0.0d,
				orientation.peakMemoryRows());
		output.putPlannedStringMetric("optimizer.hashJoinBuildSide",
				orientation.buildFromLeft() ? "left" : "right");
		output.putPlannedStringMetric("optimizer.hashJoinCandidateEstimateSource", candidates.source());
		output.putPlannedDoubleMetric("optimizer.hashJoinBuildRows", orientation.buildRows());
		output.putPlannedDoubleMetric("optimizer.hashJoinProbeInputRows", orientation.probeInputRows());
		output.putPlannedDoubleMetric("optimizer.hashJoinCandidateRows", candidates.candidateRows());
		output.putPlannedDoubleMetric("optimizer.hashJoinPeakMemoryRows", orientation.peakMemoryRows());
		output.putPlannedDoubleMetric("optimizer.hashJoinExecutionPartitions", executionPartitions);
	}

	private static double saturatedAdd(double left, double right) {
		double result = left + right;
		return Double.isFinite(result) ? result : Double.MAX_VALUE;
	}

